//! Vector test for `shared/number-format.ts` and `formatPercent` of `shared/percent.ts`: every
//! value in every locale against the output of the TS functions (Node 24 ICU), generated by a
//! throwaway script that ran them through `node --import tsx`. No TS test file exists for these.

use relay_core::shared::number_format::{format_change, format_cost, format_tokens};
use relay_core::shared::percent::format_percent;
use relay_i18n::Locale;

type Format = fn(f64, Locale) -> String;

fn check(name: &str, table: &[(f64, [&str; 15])], format: Format) {
    let mut wrong = Vec::new();
    for (value, expected) in table {
        for (locale, want) in Locale::ALL.into_iter().zip(expected) {
            let got = format(*value, locale);
            if got != *want {
                wrong.push(format!(
                    "{name}({value:?}, {}) = {got:?}, TS {want:?}",
                    locale.as_str()
                ));
            }
        }
    }
    assert!(
        wrong.is_empty(),
        "{} mismatches:\n{}",
        wrong.len(),
        wrong.join("\n")
    );
}

#[test]
fn the_tables_follow_the_locale_order() {
    assert_eq!(Locale::ALL.map(Locale::as_str), LOCALE_IDS);
}

#[test]
fn format_tokens_matches_intl_in_every_locale() {
    check("formatTokens", TOKENS, format_tokens);
}

#[test]
fn format_cost_matches_intl_in_every_locale() {
    check("formatCost", COSTS, format_cost);
}

#[test]
fn format_change_matches_intl_in_every_locale() {
    check("formatChange", CHANGES, format_change);
}

#[test]
fn format_percent_matches_intl_in_every_locale() {
    check("formatPercent", PERCENTS, |value, locale| {
        format_percent(Some(value), locale)
    });
}

